import numpy as np

def select_batch(probs, k, diversity_feats=None):
    # probs: (n, classes) from the current model on the unlabelled pool
    srt = np.sort(probs, axis=1)
    margin = srt[:, -1] - srt[:, -2]           # small margin = uncertain
    order = np.argsort(margin)
    if diversity_feats is None:
        return order[:k]                        # naive: often k near-duplicates
    picked = []
    for i in order:
        if all(np.dot(diversity_feats[i], diversity_feats[j]) < 0.9 for j in picked):
            picked.append(i)
            if len(picked) == k:
                break
    return picked
